rows.code:
#!ibl edition=2
$r = [engines:render]{path: "index.html", viewports: ["1280x800", "390x844"]}
$r.items >> [table:each] {
  [engines:image_read]{op: 'critic', image_path: $it.path, intent: f"페이지가 ${it.label} 폭에서 성립하는가", criteria: 'web', prescreen: $it.prescreen}
}

#!ibl edition=2
$r = [engines:render]{path: "landing.html", viewports: ["1440x900", "390x844"]}
$r.items >> [table:each] {
  [engines:image_read]{op: 'critic', image_path: $it.path, intent: f"landing page quality at ${it.label}", criteria: 'web', prescreen: $it.prescreen}
}

#!ibl edition=2
$r = [engines:render]{op: "xlsx", path: "거래장부.xlsx"}
$r.items >> [table:each] {
  [engines:image_read]{op: 'critic', image_path: $it.path, intent: f"장부 ${it.page} 쪽이 온전히 읽히는가", criteria: 'sheet', prescreen: $it.prescreen}
}
